      !$acc atomic update
      gp(1, ic, lane) = gp(1, ic, lane) - ga(1)
      !$acc atomic update
      gp(2, ic, lane) = gp(2, ic, lane) - ga(2)
      !$acc atomic update
      gp(3, ic, lane) = gp(3, ic, lane) - ga(3)
